#!/usr/bin/env python3
import os

def get_lstat(path):
    """Get lstat to check if path is a symlink without resolving"""
    try:
        st = os.lstat(path)
        return st.islink()
    except:
        return None

def is_regular_file(path):
    """Check if path is a regular file (not symlink, not dir)"""
    return os.path.isfile(path) and not os.path.islink(path)

def get_target(path):
    """Get the target of a symlink, or None if not a symlink"""
    if not os.path.islink(path):
        return None
    target = os.readlink(path)
    if not os.path.isabs(target):
        # Relative link - resolve relative to directory containing the link
        dir_of_link = os.path.dirname(os.path.abspath(path))
        target = os.path.normpath(os.path.join(dir_of_link, target))
    else:
        target = os.path.normpath(target)
    return target

# Start tracing
chain = []
current = '/workdir/start'

print(f"Starting at: {current}")

while True:
    chain.append(current)
    print(f"Current: {current}")

    # Check if current is a regular file
    if is_regular_file(current):
        print(f"STOP: Reached regular file {current}")
        break

    # Check if current is a symlink
    if os.path.islink(current):
        target = get_target(current)
        print(f"  -> symlink, target: {target}")
        current = target
        continue

    # Current is a directory (or other non-symlink)
    print(f"  -> directory (or other), continuing...")

    # If it's a directory, look for "next" symlink as main continuation
    if os.path.isdir(current):
        try:
            items = os.listdir(current)
            # Look for "next" symlink first (main chain)
            for item in sorted(items):
                item_path = os.path.join(current, item)
                if os.path.islink(item_path):
                    print(f"  -> found symlink '{item}' in directory, using it")
                    current = item_path
                    break
            else:
                print(f"  -> no symlinks in directory {current}")
                break
        except Exception as e:
            print(f"  -> error listing directory: {e}")
            break
    else:
        # Not a directory and not a symlink and not a file - what is it?
        print(f"  -> unknown type, breaking")
        break

print(f"\nChain ({len(chain)} items):")
for i, p in enumerate(chain):
    print(f"  {i+1}. {p}")

print(f"\nFinal path: {chain[-1]}")
