#!/usr/bin/env python3
import os

def get_target(path):
    """Get the target of a symlink, resolving relative paths"""
    if not os.path.islink(path):
        return None
    target = os.readlink(path)
    if not os.path.isabs(target):
        dir_of_link = os.path.dirname(os.path.abspath(path))
        target = os.path.normpath(os.path.join(dir_of_link, target))
    else:
        target = os.path.normpath(target)
    return target

def is_regular_file(path):
    """True if path exists and is a regular file (not symlink)"""
    return os.path.isfile(path) and not os.path.islink(path)

def is_symlink(path):
    return os.path.islink(path)

def follow_chain(start):
    chain = []
    current = os.path.abspath(start)

    while True:
        chain.append(current)
        print(f"Processing: {current}")

        # Check if regular file - stop
        if is_regular_file(current):
            print(f"  → STOP: regular file found")
            return chain, current

        # Check if symlink - follow it
        if is_symlink(current):
            target = get_target(current)
            print(f"  → symlink, target: {target}")
            current = target
            continue

        # It's a directory - need to find continuation
        if os.path.isdir(current):
            print(f"  → directory, looking for 'next' symlink")
            try:
                items = os.listdir(current)
                # Look for 'next' symlink first (main chain convention)
                for item in sorted(items):
                    item_path = os.path.join(current, item)
                    if os.path.islink(item_path):
                        print(f"  → using {item}")
                        current = item_path
                        break
                else:
                    print(f"  → no symlinks in directory")
                    break
            except Exception as e:
                print(f"  → error: {e}")
                break
        else:
            # Not a file, not a symlink, not a directory
            print(f"  → unknown type")
            break

    return chain, current

# Run
chain, final = follow_chain('/workdir/start')
print(f"\n=== Result ===")
print(f"Chain length: {len(chain)}")
print(f"Final path: {final}")
print(f"Is regular file: {is_regular_file(final)}")

# Write outputs
with open('/workdir/sol.txt', 'w') as f:
    f.write(final + '\n')
with open('/workdir/sol_chain.txt', 'w') as f:
    for p in chain:
        f.write(p + '\n')
print("\nFiles written.")
